from jsonb_to_recordset($lessons$[{"id":"curriculum-324-html-advanced-19","course_id":"html-advanced","title":"امن‌سازی پیوندهای خروجی و پنجره جدید","slug":"html-advanced-19","summary":"لینک‌های بازشونده در تب جدید باید رفتارشان برای کاربر روشن باشد؛ rel مناسب از دسترسی صفحه مقصد به window.opener جلوگیری می‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>لینک‌های بازشونده در تب جدید باید رفتارشان برای کاربر روشن باشد؛ rel مناسب از دسترسی صفحه مقصد به window.opener جلوگیری می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;a href=\"https://example.org\" target=\"_blank\" rel=\"noopener noreferrer\"&gt;منبع خارجی (در زبانه جدید)&lt;/a&gt;</code></pre><h3>تمرین</h3><p>سه لینک خارجی بساز؛ یکی در همان تب و دو مورد در تب جدید با توضیح قابل فهم برای کاربر.</p><h3>نکته فنی</h3><p>target blank بدون توضیح ممکن است کاربر را سردرگم کند؛ noopener را صریح بنویس.</p><h3>معیار موفقیت</h3><p>رفتار لینک اعلام شده و opener در دسترس صفحه مقصد نباشد.</p>","starter_code":"<a href=\"https://example.org\" target=\"_blank\" rel=\"noopener noreferrer\">منبع خارجی (در زبانه جدید)</a>","exercise":"سه لینک خارجی بساز؛ یکی در همان تب و دو مورد در تب جدید با توضیح قابل فهم برای کاربر.","status":"published","sort_order":19,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-20","course_id":"html-advanced","title":"سیاست امنیت محتوا و محدودیت‌های meta CSP","slug":"html-advanced-20","summary":"meta CSP فقط زیرمجموعه‌ای از سیاست امنیت محتوا را اعمال می‌کند و نسبت به هدر HTTP محدودیت دارد؛ سیاست سخت‌گیرانه باید در سرور تنظیم شود. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>meta CSP فقط زیرمجموعه‌ای از سیاست امنیت محتوا را اعمال می‌کند و نسبت به هدر HTTP محدودیت دارد؛ سیاست سخت‌گیرانه باید در سرور تنظیم شود.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'self'; img-src 'self' https:; object-src 'none'; base-uri 'self'\"&gt;</code></pre><h3>تمرین</h3><p>یک سیاست آزمایشی برای صفحه ایستا بنویس و مشخص کن چرا هدر HTTP برای سیاست نهایی ترجیح دارد.</p><h3>نکته فنی</h3><p>CSP را بدون آزمون منابع لازم فعال نکن؛ ممکن است اسکریپت‌ها و سبک‌های معتبر را مسدود کند.</p><h3>معیار موفقیت</h3><p>منابع مجاز محدود باشند و محدودیت meta CSP به‌درستی توضیح داده شود.</p>","starter_code":"<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'self'; img-src 'self' https:; object-src 'none'; base-uri 'self'\">","exercise":"یک سیاست آزمایشی برای صفحه ایستا بنویس و مشخص کن چرا هدر HTTP برای سیاست نهایی ترجیح دارد.","status":"published","sort_order":20,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-21","course_id":"html-advanced","title":"طراحی بارگذاری واکنشی رسانه‌های سنگین","slug":"html-advanced-21","summary":"رسانه واکنشی باید برای اندازه‌های مختلف فایل مناسب انتخاب کند؛ picture برای art direction و source type کاربرد دارد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>رسانه واکنشی باید برای اندازه‌های مختلف فایل مناسب انتخاب کند؛ picture برای art direction و source type کاربرد دارد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;picture&gt;&lt;source media=\"(max-width: 600px)\" srcset=\"small.webp\"&gt;&lt;source type=\"image/avif\" srcset=\"hero.avif\"&gt;&lt;img src=\"hero.jpg\" alt=\"نمای داشبورد آموزشی\" width=\"1200\" height=\"600\"&gt;&lt;/picture&gt;</code></pre><h3>تمرین</h3><p>برای تصویر قهرمان نسخه موبایل و دسکتاپ تعریف کن و fallback تصویری معتبر قرار بده.</p><h3>نکته فنی</h3><p>ابعاد را مشخص کن تا جابه‌جایی چیدمان کاهش یابد؛ alt را با محتوای واقعی هماهنگ کن.</p><h3>معیار موفقیت</h3><p>در مرورگرهای فاقد فرمت جدید، fallback نمایش داده شود.</p>","starter_code":"<picture><source media=\"(max-width: 600px)\" srcset=\"small.webp\"><source type=\"image/avif\" srcset=\"hero.avif\"><img src=\"hero.jpg\" alt=\"نمای داشبورد آموزشی\" width=\"1200\" height=\"600\"></picture>","exercise":"برای تصویر قهرمان نسخه موبایل و دسکتاپ تعریف کن و fallback تصویری معتبر قرار بده.","status":"published","sort_order":21,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-22","course_id":"html-advanced","title":"راهبرد preload و prefetch برای مسیرهای واقعی","slug":"html-advanced-22","summary":"preload برای منبعی است که همین صفحه قطعاً به‌زودی نیاز دارد؛ prefetch برای ناوبری احتمالی آینده است و مصرف شبکه دارد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>preload برای منبعی است که همین صفحه قطعاً به‌زودی نیاز دارد؛ prefetch برای ناوبری احتمالی آینده است و مصرف شبکه دارد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;link rel=\"preload\" href=\"/fonts/academy.woff2\" as=\"font\" type=\"font/woff2\" crossorigin&gt;&lt;link rel=\"prefetch\" href=\"/next-lesson.html\"&gt;</code></pre><h3>تمرین</h3><p>برای فونت ضروری preload و برای صفحه بعدی prefetch تعریف کن؛ هزینه بارگذاری بی‌مورد را بررسی کن.</p><h3>نکته فنی</h3><p>preload زیاد رقابت منابع را بالا می‌برد و می‌تواند عملکرد را بدتر کند.</p><h3>معیار موفقیت</h3><p>فقط منابع حیاتی preload شوند و نوع و crossorigin درست باشد.</p>","starter_code":"<link rel=\"preload\" href=\"/fonts/academy.woff2\" as=\"font\" type=\"font/woff2\" crossorigin><link rel=\"prefetch\" href=\"/next-lesson.html\">","exercise":"برای فونت ضروری preload و برای صفحه بعدی prefetch تعریف کن؛ هزینه بارگذاری بی‌مورد را بررسی کن.","status":"published","sort_order":22,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-23","course_id":"html-advanced","title":"مدیریت crossorigin در منابع خارجی","slug":"html-advanced-23","summary":"منابع cross-origin ممکن است به CORS نیاز داشته باشند؛ مقدار crossorigin باید با نوع منبع و پاسخ سرور سازگار باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>منابع cross-origin ممکن است به CORS نیاز داشته باشند؛ مقدار crossorigin باید با نوع منبع و پاسخ سرور سازگار باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;link rel=\"preload\" href=\"https://cdn.example.com/font.woff2\" as=\"font\" type=\"font/woff2\" crossorigin&gt;&lt;img src=\"https://cdn.example.com/chart.png\" alt=\"نمودار فروش\" crossorigin=\"anonymous\"&gt;</code></pre><h3>تمرین</h3><p>یک فونت و تصویر CDN تعریف کن؛ بررسی کن سرور چه هدر CORS لازم دارد و چه زمانی درخواست مسدود می‌شود.</p><h3>نکته فنی</h3><p>افزودن crossorigin به‌تنهایی مجوز سرور ایجاد نمی‌کند.</p><h3>معیار موفقیت</h3><p>درخواست با هدرهای مجاز پاسخ بگیرد و رفتار خطا توضیح داده شود.</p>","starter_code":"<link rel=\"preload\" href=\"https://cdn.example.com/font.woff2\" as=\"font\" type=\"font/woff2\" crossorigin><img src=\"https://cdn.example.com/chart.png\" alt=\"نمودار فروش\" crossorigin=\"anonymous\">","exercise":"یک فونت و تصویر CDN تعریف کن؛ بررسی کن سرور چه هدر CORS لازم دارد و چه زمانی درخواست مسدود می‌شود.","status":"published","sort_order":23,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-24","course_id":"html-advanced","title":"پخش ویدیوی آموزشی با track و caption","slug":"html-advanced-24","summary":"عنصر track زیرنویس و توضیح صوتی را به ویدیو متصل می‌کند؛ kind و srclang و label باید با فایل هماهنگ باشند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>عنصر track زیرنویس و توضیح صوتی را به ویدیو متصل می‌کند؛ kind و srclang و label باید با فایل هماهنگ باشند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;video controls preload=\"metadata\" poster=\"cover.jpg\"&gt;&lt;source src=\"lesson.mp4\" type=\"video/mp4\"&gt;&lt;track kind=\"captions\" src=\"fa.vtt\" srclang=\"fa\" label=\"فارسی\" default&gt;&lt;/video&gt;</code></pre><h3>تمرین</h3><p>برای ویدیوی آموزشی زیرنویس فارسی و انگلیسی اضافه کن و فایل WebVTT معتبر بساز.</p><h3>نکته فنی</h3><p>زیرنویس باید گفتار و صداهای مهم را پوشش دهد؛ صرف متن خودکار بررسی‌نشده کافی نیست.</p><h3>معیار موفقیت</h3><p>کاربر بتواند زیرنویس را انتخاب کند و زمان‌بندی VTT معتبر باشد.</p>","starter_code":"<video controls preload=\"metadata\" poster=\"cover.jpg\"><source src=\"lesson.mp4\" type=\"video/mp4\"><track kind=\"captions\" src=\"fa.vtt\" srclang=\"fa\" label=\"فارسی\" default></video>","exercise":"برای ویدیوی آموزشی زیرنویس فارسی و انگلیسی اضافه کن و فایل WebVTT معتبر بساز.","status":"published","sort_order":24,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-25","course_id":"html-advanced","title":"دسترسی‌پذیری رسانه با توضیح و transcript","slug":"html-advanced-25","summary":"رسانه آموزشی باید برای افراد ناشنوا، کم‌شنوا و کسانی که صدا ندارند جایگزین متنی فراهم کند؛ transcript محتوای گفتار و اطلاعات دیداری ضروری را پوشش می‌دهد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>رسانه آموزشی باید برای افراد ناشنوا، کم‌شنوا و کسانی که صدا ندارند جایگزین متنی فراهم کند؛ transcript محتوای گفتار و اطلاعات دیداری ضروری را پوشش می‌دهد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;figure&gt;&lt;video controls&gt;&lt;source src=\"lesson.mp4\" type=\"video/mp4\"&gt;&lt;/video&gt;&lt;figcaption&gt;آموزش ساخت فرم&lt;/figcaption&gt;&lt;/figure&gt;&lt;a href=\"lesson-transcript.html\"&gt;خواندن متن کامل ویدیو&lt;/a&gt;</code></pre><h3>تمرین</h3><p>برای یک ویدیوی کوتاه caption و transcript جداگانه تهیه کن و تفاوت کاربرد آن‌ها را شرح بده.</p><h3>نکته فنی</h3><p>figcaption عنوان رسانه است و جایگزین زیرنویس یا transcript نیست.</p><h3>معیار موفقیت</h3><p>محتوای صوتی و دیداری مهم بدون نیاز به پخش ویدیو قابل دریافت باشد.</p>","starter_code":"<figure><video controls><source src=\"lesson.mp4\" type=\"video/mp4\"></video><figcaption>آموزش ساخت فرم</figcaption></figure><a href=\"lesson-transcript.html\">خواندن متن کامل ویدیو</a>","exercise":"برای یک ویدیوی کوتاه caption و transcript جداگانه تهیه کن و تفاوت کاربرد آن‌ها را شرح بده.","status":"published","sort_order":25,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-26","course_id":"html-advanced","title":"طراحی تجربه چاپ با ساختار معنایی","slug":"html-advanced-26","summary":"ساختار چاپ باید ترتیب خواندن و اطلاعات ضروری را حفظ کند؛ کنترل‌های تعاملی غیرضروری نباید در نسخه چاپی غالب باشند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>ساختار چاپ باید ترتیب خواندن و اطلاعات ضروری را حفظ کند؛ کنترل‌های تعاملی غیرضروری نباید در نسخه چاپی غالب باشند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;article&gt;&lt;h1&gt;گزارش دوره&lt;/h1&gt;&lt;p&gt;خلاصه پیشرفت دانش‌آموز&lt;/p&gt;&lt;a href=\"/details\"&gt;جزئیات آنلاین&lt;/a&gt;&lt;/article&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>یک گزارش قابل چاپ طراحی کن؛ مشخص کن کدام داده‌ها باید در چاپ باقی بمانند و کدام کنترل‌ها فقط برای صفحه‌اند.</p><h3>نکته فنی</h3><p>قواعد چاپ عمدتاً در CSS @media print هستند؛ HTML باید معنای محتوا را درست ارائه کند.</p><h3>معیار موفقیت</h3><p>بدون کنترل‌های تعاملی نیز گزارش چاپی قابل فهم باشد.</p>","starter_code":"<main><article><h1>گزارش دوره</h1><p>خلاصه پیشرفت دانش‌آموز</p><a href=\"/details\">جزئیات آنلاین</a></article></main>","exercise":"یک گزارش قابل چاپ طراحی کن؛ مشخص کن کدام داده‌ها باید در چاپ باقی بمانند و کدام کنترل‌ها فقط برای صفحه‌اند.","status":"published","sort_order":26,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-27","course_id":"html-advanced","title":"بهبود سازگاری با زبان و نویسه‌های ترکیبی","slug":"html-advanced-27","summary":"زبان‌های ترکیبی، نام‌ها و متن‌های با جهت متفاوت نیازمند نشانه‌گذاری دقیق‌اند؛ bdi متن با جهت ناشناخته را ایزوله می‌کند و bdo جهت را به‌زور تغییر می‌دهد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>زبان‌های ترکیبی، نام‌ها و متن‌های با جهت متفاوت نیازمند نشانه‌گذاری دقیق‌اند؛ bdi متن با جهت ناشناخته را ایزوله می‌کند و bdo جهت را به‌زور تغییر می‌دهد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;p&gt;شناسه کاربر: &lt;bdi&gt;user_علی_27&lt;/bdi&gt;&lt;/p&gt;&lt;p&gt;کد: &lt;bdi&gt;AB-1209&lt;/bdi&gt;&lt;/p&gt;</code></pre><h3>تمرین</h3><p>در یک فهرست فارسی، نام کاربری لاتین و کدهای ترکیبی قرار بده و از bdi در جای درست استفاده کن.</p><h3>نکته فنی</h3><p>bdo را برای اصلاح عمومی متن به کار نبر؛ جهت واقعی محتوا را حفظ کن.</p><h3>معیار موفقیت</h3><p>ترکیب فارسی و لاتین بدون به‌هم‌ریختگی نمایش داده شود.</p>","starter_code":"<p>شناسه کاربر: <bdi>user_علی_27</bdi></p><p>کد: <bdi>AB-1209</bdi></p>","exercise":"در یک فهرست فارسی، نام کاربری لاتین و کدهای ترکیبی قرار بده و از bdi در جای درست استفاده کن.","status":"published","sort_order":27,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-28","course_id":"html-advanced","title":"ساختاردهی محتوای زمان‌مند و داده‌های ماشین‌خوان","slug":"html-advanced-28","summary":"داده زمان باید هم برای انسان و هم ماشین خوانا باشد؛ time با datetime مقدار استاندارد قابل پردازش ارائه می‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>داده زمان باید هم برای انسان و هم ماشین خوانا باشد؛ time با datetime مقدار استاندارد قابل پردازش ارائه می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;time datetime=\"2026-11-07T18:30:00+04:30\"&gt;۷ نوامبر ۲۰۲۶، ساعت ۱۸:۳۰&lt;/time&gt;</code></pre><h3>تمرین</h3><p>برای تاریخ انتشار، مهلت تحویل و مدت یک رویداد از time با datetime معتبر استفاده کن.</p><h3>نکته فنی</h3><p>متن نمایشی و مقدار machine-readable باید به یک زمان اشاره کنند.</p><h3>معیار موفقیت</h3><p>مقدار datetime معتبر و با متن قابل مشاهده سازگار باشد.</p>","starter_code":"<time datetime=\"2026-11-07T18:30:00+04:30\">۷ نوامبر ۲۰۲۶، ساعت ۱۸:۳۰</time>","exercise":"برای تاریخ انتشار، مهلت تحویل و مدت یک رویداد از time با datetime معتبر استفاده کن.","status":"published","sort_order":28,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-29","course_id":"html-advanced","title":"ارتقای تدریجی قابلیت‌ها بدون وابستگی اجباری","slug":"html-advanced-29","summary":"Progressive enhancement یعنی محتوای اصلی بدون قابلیت‌های اضافی هم در دسترس باشد؛ قابلیت‌های پیشرفته پس از آن افزوده می‌شوند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>Progressive enhancement یعنی محتوای اصلی بدون قابلیت‌های اضافی هم در دسترس باشد؛ قابلیت‌های پیشرفته پس از آن افزوده می‌شوند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;form action=\"/search\" method=\"get\"&gt;&lt;label for=\"q\"&gt;جست‌وجو&lt;/label&gt;&lt;input id=\"q\" name=\"q\"&gt;&lt;button&gt;جست‌وجو&lt;/button&gt;&lt;/form&gt;</code></pre><h3>تمرین</h3><p>یک جست‌وجوی ساده بساز که بدون JavaScript نیز با GET کار کند؛ سپس قابلیت پیشنهاد زنده را به‌عنوان افزونه طراحی کن.</p><h3>نکته فنی</h3><p>از ابتدا عملکرد اصلی را به JavaScript وابسته نکن.</p><h3>معیار موفقیت</h3><p>عملکرد پایه با خاموش بودن JavaScript قابل استفاده باشد.</p>","starter_code":"<form action=\"/search\" method=\"get\"><label for=\"q\">جست‌وجو</label><input id=\"q\" name=\"q\"><button>جست‌وجو</button></form>","exercise":"یک جست‌وجوی ساده بساز که بدون JavaScript نیز با GET کار کند؛ سپس قابلیت پیشنهاد زنده را به‌عنوان افزونه طراحی کن.","status":"published","sort_order":29,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-30","course_id":"html-advanced","title":"طراحی HTML مقاوم در برابر محتوای ناقص","slug":"html-advanced-30","summary":"HTML مقاوم باید در برابر داده ناقص همچنان قابل فهم بماند؛ fallback و محتوای جایگزین بخشی از طراحی است. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>HTML مقاوم باید در برابر داده ناقص همچنان قابل فهم بماند؛ fallback و محتوای جایگزین بخشی از طراحی است.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;picture&gt;&lt;source srcset=\"diagram.webp\" type=\"image/webp\"&gt;&lt;img src=\"diagram.png\" alt=\"نمودار مراحل ثبت‌نام\"&gt;&lt;/picture&gt;&lt;noscript&gt;&lt;p&gt;برای امکانات تعاملی، JavaScript را فعال کن؛ محتوای اصلی در دسترس است.&lt;/p&gt;&lt;/noscript&gt;</code></pre><h3>تمرین</h3><p>یک صفحه آموزشی طراحی کن که تصویر فرمت جدید یا اسکریپت آن بارگیری نشد، پیام و محتوای اصلی همچنان قابل استفاده باشد.</p><h3>نکته فنی</h3><p>noscript جایگزین طراحی کامل بدون JavaScript نیست؛ فقط پیام/محتوای جایگزین ارائه می‌کند.</p><h3>معیار موفقیت</h3><p>شکست یک منبع، کل محتوای آموزشی را غیرقابل استفاده نکند.</p>","starter_code":"<picture><source srcset=\"diagram.webp\" type=\"image/webp\"><img src=\"diagram.png\" alt=\"نمودار مراحل ثبت‌نام\"></picture><noscript><p>برای امکانات تعاملی، JavaScript را فعال کن؛ محتوای اصلی در دسترس است.</p></noscript>","exercise":"یک صفحه آموزشی طراحی کن که تصویر فرمت جدید یا اسکریپت آن بارگیری نشد، پیام و محتوای اصلی همچنان قابل استفاده باشد.","status":"published","sort_order":30,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-31","course_id":"html-advanced","title":"ارزیابی ساختار با اعتبارسنجی و درخت دسترس‌پذیری","slug":"html-advanced-31","summary":"اعتبارسنجی HTML خطاهای ساختاری را پیدا می‌کند؛ درخت دسترس‌پذیری نشان می‌دهد فناوری کمکی چه نام و نقشی دریافت می‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>اعتبارسنجی HTML خطاهای ساختاری را پیدا می‌کند؛ درخت دسترس‌پذیری نشان می‌دهد فناوری کمکی چه نام و نقشی دریافت می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;h1&gt;ثبت‌نام&lt;/h1&gt;&lt;form&gt;&lt;label for=\"name\"&gt;نام&lt;/label&gt;&lt;input id=\"name\" name=\"name\" required&gt;&lt;button&gt;ارسال&lt;/button&gt;&lt;/form&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>یک صفحه را با validator بررسی کن، سپس در ابزار توسعه‌دهنده درخت دسترس‌پذیری را باز کن و سه ایراد را مستند کن.</p><h3>نکته فنی</h3><p>validator به‌تنهایی کیفیت دسترس‌پذیری یا تجربه کاربری را تضمین نمی‌کند.</p><h3>معیار موفقیت</h3><p>خطاهای معتبر رفع شوند و نقش و نام کنترل‌ها در accessibility tree دیده شود.</p>","starter_code":"<main><h1>ثبت‌نام</h1><form><label for=\"name\">نام</label><input id=\"name\" name=\"name\" required><button>ارسال</button></form></main>","exercise":"یک صفحه را با validator بررسی کن، سپس در ابزار توسعه‌دهنده درخت دسترس‌پذیری را باز کن و سه ایراد را مستند کن.","status":"published","sort_order":31,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-32","course_id":"html-advanced","title":"ممیزی صفحه برای خزنده و کاربر صفحه‌خوان","slug":"html-advanced-32","summary":"ممیزی حرفه‌ای باید ترتیب headingها، landmarkها، نام کنترل‌ها، متن جایگزین و پیوندهای تکراری را بررسی کند؛ ارزیابی خودکار کافی نیست. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>ممیزی حرفه‌ای باید ترتیب headingها، landmarkها، نام کنترل‌ها، متن جایگزین و پیوندهای تکراری را بررسی کند؛ ارزیابی خودکار کافی نیست.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;h1&gt;دوره‌ها&lt;/h1&gt;&lt;section aria-labelledby=\"popular\"&gt;&lt;h2 id=\"popular\"&gt;محبوب&lt;/h2&gt;&lt;ul&gt;&lt;li&gt;&lt;a href=\"/html\"&gt;دوره HTML&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>برای صفحه‌ای با چند بخش، یک چک‌لیست ممیزی بساز و با صفحه‌خوان یا پیمایش صفحه‌کلید موارد را دستی بررسی کن.</p><h3>نکته فنی</h3><p>امتیاز ابزار خودکار معادل دسترس‌پذیری کامل نیست.</p><h3>معیار موفقیت</h3><p>حداقل یک آزمون خودکار و یک آزمون دستی مستند شود.</p>","starter_code":"<main><h1>دوره‌ها</h1><section aria-labelledby=\"popular\"><h2 id=\"popular\">محبوب</h2><ul><li><a href=\"/html\">دوره HTML</a></li></ul></section></main>","exercise":"برای صفحه‌ای با چند بخش، یک چک‌لیست ممیزی بساز و با صفحه‌خوان یا پیمایش صفحه‌کلید موارد را دستی بررسی کن.","status":"published","sort_order":32,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-33","course_id":"html-advanced","title":"طراحی صفحه خطا و وضعیت‌های خالی","slug":"html-advanced-33","summary":"صفحه وضعیت خالی و خطا باید دلیل و مسیر اقدام بعدی را روشن کند؛ پیام نباید فقط یک کد یا رنگ باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>صفحه وضعیت خالی و خطا باید دلیل و مسیر اقدام بعدی را روشن کند؛ پیام نباید فقط یک کد یا رنگ باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;h1&gt;دوره‌ای پیدا نشد&lt;/h1&gt;&lt;p&gt;این دوره هنوز منتشر نشده است.&lt;/p&gt;&lt;a href=\"/courses\"&gt;مشاهده همه دوره‌ها&lt;/a&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>برای حالت خالی، خطای ۴۰۴ و خطای بارگیری سه صفحه مجزا بساز و برای هرکدام مسیر بازیابی تعریف کن.</p><h3>نکته فنی</h3><p>خطای سرور را به‌عنوان نبودن محتوا نمایش نده؛ وضعیت‌ها معنای متفاوت دارند.</p><h3>معیار موفقیت</h3><p>کاربر دلیل وضعیت و اقدام بعدی را بفهمد.</p>","starter_code":"<main><h1>دوره‌ای پیدا نشد</h1><p>این دوره هنوز منتشر نشده است.</p><a href=\"/courses\">مشاهده همه دوره‌ها</a></main>","exercise":"برای حالت خالی، خطای ۴۰۴ و خطای بارگیری سه صفحه مجزا بساز و برای هرکدام مسیر بازیابی تعریف کن.","status":"published","sort_order":33,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-34","course_id":"html-advanced","title":"ساخت الگوی ناوبری عمیق برای سایت چندصفحه‌ای","slug":"html-advanced-34","summary":"ناوبری عمیق در سایت چندصفحه‌ای باید مسیر فعلی، بخش‌های اصلی و پیوندهای بازگشت را مشخص کند؛ ساختار باید در همه صفحات سازگار بماند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>ناوبری عمیق در سایت چندصفحه‌ای باید مسیر فعلی، بخش‌های اصلی و پیوندهای بازگشت را مشخص کند؛ ساختار باید در همه صفحات سازگار بماند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;nav aria-label=\"مسیر صفحه\"&gt;&lt;ol&gt;&lt;li&gt;&lt;a href=\"/\"&gt;خانه&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a href=\"/academy\"&gt;آکادمی&lt;/a&gt;&lt;/li&gt;&lt;li aria-current=\"page\"&gt;HTML پیشرفته&lt;/li&gt;&lt;/ol&gt;&lt;/nav&gt;</code></pre><h3>تمرین</h3><p>برای سه صفحه تو‌در‌تو breadcrumb بساز و aria-current را فقط روی صفحه جاری قرار بده.</p><h3>نکته فنی</h3><p>breadcrumb جایگزین منوی اصلی نیست و نباید مسیر ساختگی نشان دهد.</p><h3>معیار موفقیت</h3><p>مسیر واقعی صفحه و وضعیت جاری برای فناوری کمکی مشخص باشد.</p>","starter_code":"<nav aria-label=\"مسیر صفحه\"><ol><li><a href=\"/\">خانه</a></li><li><a href=\"/academy\">آکادمی</a></li><li aria-current=\"page\">HTML پیشرفته</li></ol></nav>","exercise":"برای سه صفحه تو‌در‌تو breadcrumb بساز و aria-current را فقط روی صفحه جاری قرار بده.","status":"published","sort_order":34,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-35","course_id":"html-advanced","title":"پروژه نهایی: وب‌سایت مستندات چندزبانه","slug":"html-advanced-35","summary":"پروژه نهایی باید چند صفحه واقعی، ناوبری یکپارچه، metadata یکتا، ساختار معنایی، رسانه دسترس‌پذیر و fallback داشته باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>پروژه نهایی باید چند صفحه واقعی، ناوبری یکپارچه، metadata یکتا، ساختار معنایی، رسانه دسترس‌پذیر و fallback داشته باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;header&gt;&lt;a href=\"/\"&gt;آکادمی NEXORA FORGE&lt;/a&gt;&lt;nav aria-label=\"اصلی\"&gt;&lt;a href=\"/courses\"&gt;دوره‌ها&lt;/a&gt;&lt;/nav&gt;&lt;/header&gt;&lt;main&gt;&lt;article&gt;&lt;h1&gt;HTML پیشرفته&lt;/h1&gt;&lt;p&gt;مسیر یادگیری استاندارد وب&lt;/p&gt;&lt;/article&gt;&lt;/main&gt;&lt;footer&gt;© NEXORA FORGE&lt;/footer&gt;</code></pre><h3>تمرین</h3><p>یک وب‌سایت مستندات سه‌صفحه‌ای بساز: خانه، فهرست دوره‌ها و صفحه درس. برای هر صفحه عنوان، توضیح، canonical، breadcrumb و ساختار معنایی مستقل قرار بده.</p><h3>نکته فنی</h3><p>کپی‌کردن یک metadata ثابت برای همه صفحات خطاست؛ هر URL باید اطلاعات متناسب خودش را داشته باشد.</p><h3>معیار موفقیت</h3><p>هر سه صفحه با پیوندهای واقعی، عنوان یکتا، دسترس‌پذیری پایه و HTML معتبر کار کنند.</p>","starter_code":"<header><a href=\"/\">آکادمی NEXORA FORGE</a><nav aria-label=\"اصلی\"><a href=\"/courses\">دوره‌ها</a></nav></header><main><article><h1>HTML پیشرفته</h1><p>مسیر یادگیری استاندارد وب</p></article></main><footer>© NEXORA FORGE</footer>","exercise":"یک وب‌سایت مستندات سه‌صفحه‌ای بساز: خانه، فهرست دوره‌ها و صفحه درس. برای هر صفحه عنوان، توضیح، canonical، breadcrumb و ساختار معنایی مستقل قرار بده.","status":"published","sort_order":35,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-36","course_id":"html-advanced","title":"ارزیابی نهایی استاندارد، امنیت و کیفیت HTML","slug":"html-advanced-36","summary":"در ارزیابی نهایی باید صحت استاندارد، امنیت، سازگاری، دسترس‌پذیری و عملکرد را جداگانه بررسی کنی و شواهد آزمون را ثبت کنی. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>در ارزیابی نهایی باید صحت استاندارد، امنیت، سازگاری، دسترس‌پذیری و عملکرد را جداگانه بررسی کنی و شواهد آزمون را ثبت کنی.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;h1&gt;گزارش ممیزی HTML&lt;/h1&gt;&lt;ol&gt;&lt;li&gt;اعتبارسنجی ساختار&lt;/li&gt;&lt;li&gt;آزمون صفحه‌کلید&lt;/li&gt;&lt;li&gt;بررسی metadata&lt;/li&gt;&lt;li&gt;بررسی منابع خارجی&lt;/li&gt;&lt;/ol&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>پروژه نهایی را با یک جدول ممیزی ارزیابی کن؛ برای هر ایراد، شدت، اثر، روش بازتولید و اصلاح را بنویس.</p><h3>نکته فنی</h3><p>عبارت «بدون خطا» را بدون آزمون مستند استفاده نکن.</p><h3>معیار موفقیت</h3><p>گزارش شامل نتیجه آزمون، ایرادهای باقی‌مانده و محدودیت‌های بررسی باشد.</p>","starter_code":"<main><h1>گزارش ممیزی HTML</h1><ol><li>اعتبارسنجی ساختار</li><li>آزمون صفحه‌کلید</li><li>بررسی metadata</li><li>بررسی منابع خارجی</li></ol></main>","exercise":"پروژه نهایی را با یک جدول ممیزی ارزیابی کن؛ برای هر ایراد، شدت، اثر، روش بازتولید و اصلاح را بنویس.","status":"published","sort_order":36,"estimated_minutes":40}]$lessons$::jsonb) as x(id text,course_id text,title text,slug text,summary text,content_html text,starter_code text,exercise text,status text,sort_order integer,estimated_minutes integer)
join (values
('html','html','beginner'),('html-intermediate','html','intermediate'),('html-advanced','html','advanced'),
('css','css','beginner'),('css-intermediate','css','intermediate'),('css-advanced','css','advanced'),
('javascript','javascript','beginner'),('javascript-intermediate','javascript','intermediate'),('javascript-advanced','javascript','advanced')
) as cp(course_id,language_id,level_id) on cp.course_id=x.course_id
join public.academy_courses c on c.language_id=cp.language_id and c.level_id=cp.level_id
on conflict(id) do update set title=excluded.title,slug=excluded.slug,summary=excluded.summary,content_html=excluded.content_html,starter_code=excluded.starter_code,exercise=excluded.exercise,status='published',sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,archived_at=null,updated_at=now();

